};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_basinfo_tbl_OnLoadCompleted = function(e) {
};

scwin.MxDataSet_basinfo_col_OnLoadCompleted = function(e) {
};

scwin.MxDataSet_mapping_list_OnLoadCompleted = function(e) {
};

