};

scwin.MxDataSet_form_itm_OnLoadCompleted = function(e) {

};

scwin.MxDataSet_mapping_one_OnLoadCompleted = function(e) {
};

scwin.grd_basinfotbl_OnClick = function(row, colid) {
    try {
        scwin.table_nm = MxDataSet_basinfo_tbl.getCellData(row, "TABLE_NM");
        scwin.remk = MxDataSet_basinfo_tbl.getCellData(row, "REMK");
        scwin.mapp_tp_cd = MxDataSet_basinfo_tbl.getCellData(row, "MAPP_TP_CD");
        etc_gubun.setValue("0"); // 기본정보 테이블 변경 할 경우 구분은 해당없음으로
        scwin.basinfoColumn();
        MxDataSet_mapping_one.setJSON([]);
        MxDataSet_mapping_one.insertRow();
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TRM_ENG_NM", "");
        // MxDataSet_mapping_one.NameValue(MxDataSet_mapping_one.RowPosition, "MAPP_TP_CD") = mapp_tp_cd;
        let unitFormChk = cbo_unitForm.getSelectedIndex() + 1;
        if (unitFormChk === "0") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", "0");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", "2");
        }
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_CD", scwin.ownr_form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_VER", scwin.ownr_form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_CD", scwin.form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_VER", scwin.form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_CD", scwin.elmt_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_VER", scwin.elmt_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_X_PATH", scwin.form_x_path);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FSS_ELMT_ID", "");

        let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "LD_MKT_TP_CD", ssval);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.grd_basinfotbl_OnClick" });
    }
};

scwin.grd_basinfocol_OnClick = function(row, colid) {
    try {
        scwin.table_nm = MxDataSet_basinfo_col.getCellData(row, "TABLE_NM");
        scwin.column_nm = MxDataSet_basinfo_col.getCellData(row, "COLUMN_NM");
        scwin.comments = MxDataSet_basinfo_col.getCellData(row, "COMMENTS");
        etc_gubun.setValue("0"); // 기본정보 항목 변경 할 경우 구분은 해당없음으로
        scwin.mappingList("combas");
        MxDataSet_mapping_one.setJSON([]);
        MxDataSet_mapping_one.insertRow();
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TRM_ENG_NM", scwin.column_nm);
        // MxDataSet_mapping_one.NameValue(MxDataSet_mapping_one.RowPosition, "MAPP_TP_CD") = mapp_tp_cd;
        let unitFormChk = cbo_unitForm.getSelectedIndex() + 1;
        if (unitFormChk === "0") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", "0");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", "2");
        }
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_CD", scwin.ownr_form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_VER", scwin.ownr_form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_CD", scwin.form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_VER", scwin.form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_CD", scwin.elmt_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_VER", scwin.elmt_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_X_PATH", scwin.form_x_path);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FSS_ELMT_ID", "");

        let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "LD_MKT_TP_CD", ssval);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.grd_basinfocol_OnClick" });
    }
};

scwin.form_search_onclick = function(e) {
    try {
        cbo_unitForm.Index = -1;
        txb_formXPath.setValue("");
        scwin.formnm_row = "0";
        scwin.formSearch();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.form_search_onclick" });
    }
};

scwin.grid_formnm_OnClick = function(row, colid) {
    try {
        cbo_unitForm.Index = -1;
        txb_formXPath.setValue("");
        scwin.ownr_form_cd = MxDataSet_form.getCellData(row, "OWNR_FORM_CD");
        scwin.ownr_form_ver = MxDataSet_form.getCellData(row, "OWNR_FORM_VER");
        scwin.form_cd = MxDataSet_form.getCellData(row, "OWNR_FORM_CD");
        txb_formXPath.setValue("");
        scwin.formnm_row = row;
        scwin.formItmSearch();
        MxDataSet_mapping_one.setJSON([]);
        MxDataSet_mapping_one.insertRow();
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_CD", scwin.ownr_form_cd);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_VER", scwin.ownr_form_ver);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TRM_ENG_NM", scwin.column_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", scwin.mapp_tp_cd);

        let formgubun = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
        if (formgubun !== "9") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_CD", "");
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_VER", "");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_CD", scwin.ownr_form_cd);
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_VER", scwin.ownr_form_ver);
            scwin.form_ver = MxDataSet_form.getCellData(row, "OWNR_FORM_VER");
        }
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_CD", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_VER", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FSS_ELMT_ID", "");

        let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "LD_MKT_TP_CD", ssval);
        scwin.mappingList("formbas");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.grid_formnm_OnClick" });
    }
};

scwin.grid_formitm_OnClick = function(row, colid) {
    try {
        scwin.form_cd = MxDataSet_form_itm.getCellData(row, "FORM_CD");
        scwin.form_ver = MxDataSet_form_itm.getCellData(row, "FORM_VER");
        scwin.elmt_cd = MxDataSet_form_itm.getCellData(row, "ELMT_CD");
        scwin.elmt_ver = MxDataSet_form_itm.getCellData(row, "ELMT_VER");
        scwin.form_x_path = MxDataSet_form_itm.getCellData(row, "FORM_X_PATH");
        txb_formXPath.setValue(scwin.form_x_path);
        scwin.mappingOne();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.grid_formitm_OnClick" });
    }
};

scwin.img_save_onclick = function(e) {
    try {
        scwin.mappingSave();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.img_save_onclick" });
    }
};

scwin.img_delete_onclick = function(e) {
    try {
        scwin.delete(MxDataSet_mapping_list, 'MxDataSet_mapping_list');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.img_delete_onclick" });
    }
};

scwin.MxLogicalTr_mapping_save_OnSuccess = function(e) {
    try {
        alert('저장이 완료되었습니다.');
        txb_formXPath.setValue("");
        MxDataSet_mapping_one.setJSON([]);
        scwin.mappingList("formitmbas");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.MxLogicalTr_mapping_save_OnSuccess" });
    }
};

scwin.MxLogicalTr_mapping_save_OnFail = function(e) {
    try {
        alert('저장에 실패했습니다.');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.MxLogicalTr_mapping_save_OnFail" });
    }
};

scwin.MxLogicalTr_mapping_delete_OnSuccess = function(e) {
    try {
        alert('삭제되었습니다.');
        scwin.mappingList("formbas");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.MxLogicalTr_mapping_delete_OnSuccess" });
    }
};

scwin.MxLogicalTr_mapping_delete_OnFail = function(e) {
    try {
        alert('삭제 실패했습니다.');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.MxLogicalTr_mapping_delete_OnFail" });
    }
};

scwin.etc_gubun_onclick = function(index, value) {
    try {
        scwin.etcCheck();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.etc_gubun_onclick" });
    }
};

scwin.txb_formnm_onkeydown = function(e) {
    try {
        if (window.event.keyCode === "13") {
            cbo_unitForm.Index = -1;
            txb_formXPath.setValue("");
            scwin.formnm_row = "0";
            scwin.formSearch();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.txb_formnm_onkeydown" });
    }
};

scwin.cbo_unitForm_onselchange = function(info) {
    try {
        // comboFormGubun.Index = -1;
        // txb_formnm.value = "";
        txb_formXPath.setValue("");
        // MxDataSet_form.ClearData();
        MxDataSet_form_itm.setJSON([]);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_CD", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_VER", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_CD", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_VER", "");
        scwin.unitFormItmSearch();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.cbo_unitForm_onselchange" });
    }
};

scwin.comboFormGubun_onselchange = function(info) {
    try {
        // cbo_unitForm.Index = -1;
        // txb_formXPath.value = "";
        MxDataSet_form_itm.setJSON([]);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_CD", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_VER", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_CD", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_VER", "");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.comboFormGubun_onselchange" });
    }
};

scwin.img_modify_onclick = function(e) {
    try {
        scwin.mappingModify();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT95000.img_modify_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.basinfoTable = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_basinfo_tbl",
        action : "/kclic.do",
        ref : "",
        target : "MxDataSet_basinfo_tbl=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.basinfoColumn = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_basinfo_col",
        action : "/kclic.do",
        ref : "",
        target : "MxDataSet_basinfo_col=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.mappingList = async function(comformetcgubun) {
    let url = "";
    if (comformetcgubun === "etcbas") {
        url = "/kclic.do?method=searchMappingList&inputMessageId=infoBasForm&outputMessageIdinfoBasForm" + "&TABLE_NM=" + scwin.table_nm + "&COLUMN_NM=" + scwin.column_nm + "&COMFORMETCGUBUN=" + comformetcgubun + "&FORM_CD=" + scwin.form_cd + "&FORM_VER=" + scwin.form_ver + "&ELMT_CD=" + scwin.elmt_cd + "&ELMT_VER=" + scwin.elmt_ver + "&MAPP_TP_CD=" + etc_gubun.getValue() + "&OWNR_FORM_CD=" + scwin.ownr_form_cd + "&OWNR_FORM_VER=" + scwin.ownr_form_ver;
    } else {
    }
    const sbmOptions = {
        id : "sbm_MxDataSet_mapping_list",
        action : "/kclic.do",
        ref : "",
        target : "MxDataSet_mapping_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.formSearch = async function() {
    const sData = comboFormGubun.getSelectedIndex() + 1;

    let formgubun = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
    if (sData === 0) {
        alert("시장구분을 선택해주십시오");
        return;
    }
    if (txb_formnm.value === "") {
        alert("서식명을 입력하십시오");
        return;
    }
    MxDataSet_form_itm.setJSON([]);
    const sbmOptions = {
        id : "sbm_MxDataSet_form",
        action : "/kclic.do",
        ref : "",
        target : "MxDataSet_form=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.formItmSearch = async function() {

    let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
    if (ssval === "9") {
        // 금감원 서식일 경우 팝업창
        // 2018-05-04 변경
        const pageURL = in_kclic_url + "/submission/formAdmin.do?method=searchDartFormIframe&formCd=" + scwin.form_cd;

        window.open(pageURL, "fssPop", "scrollbars=yes,toolbar=no,resizable=yes,width=835,height=695,left=10,top=10");
    } else {
        // 금감원 서식 아닐 경우 항목 조회
        // alert(ownr_form_cd+" / "+ownr_form_ver);
        //+ssval+"&FORM_SEARCH_TXT="+txb_formnm.value+"&FORMNM_ROW="+formnm_row;
        const sbmOptions = {
            id : "sbm_MxDataSet_form_itm",
            action : "/kclic.do",
            ref : "",
            target : "MxDataSet_form_itm=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

scwin.unitFormItmSearch = async function() {

    const unitFormCd = cbo_unitForm.ValueOfIndex("Column1", cbo_unitForm.getSelectedIndex());
    MxDataSet_form_itm.setJSON([]);
    const sbmOptions = {
        id : "sbm_MxDataSet_form_itm",
        action : "/kclic.do",
        ref : "",
        target : "MxDataSet_form_itm=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.mappingSave = async function() {
    t_TableNm = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TABLE_NM");
    t_TrmEngNm = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TRM_ENG_NM");
    t_EtcGubunValue = etc_gubun.getValue();

    let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
    if (t_EtcGubunValue === "0") {
        if (t_TableNm === "") {
            alert("기본정보 테이블을 선택하십시오.");
            return;
        }
        if (t_TrmEngNm === "") {
            alert("기본정보 항목을 선택하십시오.");
            return;
        }
    }
    if (ssval !== "9") {
        // 서식검색이 금감원이 아닐 경우
        if (txb_formXPath.value === "") {
            alert("서식(서식명, 항목)을 선택하십시오.");
            return;
        }
    }
    if (ssval === "9") {
        // 서식검색이 금감원일 경우
        scwin.elmt_cd = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_CD");
        if (scwin.elmt_cd === "") {
            alert("금감원 서식일 경우 엘리먼트 코드를 입력하십시오");
            return;
        }
        scwin.mapp_tp_cd = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD");
        if (scwin.mapp_tp_cd !== "A" && scwin.mapp_tp_cd !== "B" && scwin.mapp_tp_cd !== "C" && scwin.mapp_tp_cd !== "D" && scwin.mapp_tp_cd !== "E" && scwin.mapp_tp_cd !== "F") {
            alert("금감원 서식일 경우 구분값을 A, B, C, D, E, F 중 입력하십시오");
            return;
        }
        scwin.fss_elmt_id = MxDataSet_mapping_one.getCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FSS_ELMT_ID");
        if (scwin.fss_elmt_id === "") {
            alert("금감원 서식일 경우 FSS_ELMT_ID를 입력하십시오");
            return;
        }
    }
    if (confirm("저장하시겠습니까?")) {
        MxLogicalTr_mapping_save.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_MxLogicalTr_mapping_save",
            action : "/kclic.do",
            ref : "MxDataSet_mapping_one",
            target : "MxLogicalTr_mapping_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        MxDataSet_mapping_one.setJSON([]);
    }
};

scwin.mappingModify = async function() {

    let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
    if (scwin.ownr_form_cd === "" || scwin.ownr_form_ver === "") {
        alert("서식명을 선택하십시오.");
        return;
    }
    if (scwin.formnm_row === 0) {
        alert("서식명을 선택하십시오.");
        return;
    }
    const m_form_ver = MxDataSet_form.getCellData(scwin.formnm_row, "OWNR_FORM_VER");
    if (typeof m_form_ver !== "undefined" && m_form_ver !== "") {
        let maxVal;
        let tmpVal1;
        let tmpVal2;
        const f_form_ver = parseFloat(m_form_ver);
        if (f_form_ver === maxVal) {
            alert("같은 폼 버전의 데이터가 있어 서식버전 업데이트를 할 수 없습니다.");
        } else {
            if (confirm("서식버전을 변경하시겠습니까?")) {
                const sbmOptions = {
                    id : "sbm_MxDataSet_mapping_list",
                    action : "/kclic.do",
                    ref : "",
                    target : "MxDataSet_mapping_list=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            }
        }
    } else {
        alert("변경할 데이터가 업습니다.");
    }
};

scwin.delete = async function(sval, sval2) {
    let delCnt = 0;
    if (!scwin.cntDatasetRowCheck(sval)) {
        alert("체크사항이 없습니다.");
        return;
    } else {
        for (i = sval.countrow; i > 0; i--) {
            if (sval.NameValue(i, "CHK_FLAG") === "T") {
                delCnt++;
                // sval.DeleteRow(i);

            }
        }
    }
    if (confirm(delCnt + "건을 삭제하시겠습니까?")) {
        for (i = sval.countrow; i > 0; i--) {
            if (sval.NameValue(i, "CHK_FLAG") === "T") {
                sval.DeleteRow(i);
            }
        }
        MxLogicalTr_mapping_delete.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_MxLogicalTr_mapping_delete",
            action : "/kclic.do",
            ref : "MxDataSet_mapping_list",
            target : "MxLogicalTr_mapping_delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.mappingOne = function() {
    MxDataSet_mapping_one.setJSON([]);
    MxDataSet_mapping_one.insertRow();
    if (etc_gubun.getValue() === '3' || etc_gubun.getValue() === '1' || etc_gubun.getValue() === '5' || etc_gubun.getValue() === '6') {
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TABLE_NM", "");
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TRM_ENG_NM", "");
    } else {
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TABLE_NM", scwin.table_nm);
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "TRM_ENG_NM", scwin.column_nm);
    }
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_CD", scwin.ownr_form_cd);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "OWNR_FORM_VER", scwin.ownr_form_ver);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_CD", scwin.form_cd);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_VER", scwin.form_ver);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_CD", scwin.elmt_cd);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "ELMT_VER", scwin.elmt_ver);
    if (etc_gubun.getValue() === '3' || etc_gubun.getValue() === '1' || etc_gubun.getValue() === '2' || etc_gubun.getValue() === '4' || etc_gubun.getValue() === '5' || etc_gubun.getValue() === '6') {
        MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", etc_gubun.getValue());
    } else {
        let unitFormChk = cbo_unitForm.getSelectedIndex() + 1;
        if (unitFormChk === "0") {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", "0");
        } else {
            MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "MAPP_TP_CD", "7");
        }
    }
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FSS_ELMT_ID", "");

    let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "LD_MKT_TP_CD", ssval);
    MxDataSet_mapping_one.setCellData(MxDataSet_mapping_one.getFocusedRowIndex(), "FORM_X_PATH", scwin.form_x_path);
    if (etc_gubun.getValue() === '3' || etc_gubun.getValue() === '1' || etc_gubun.getValue() === '6') {
        scwin.mappingList("etcbas");
    } else {
        scwin.mappingList("formitmbas");
    }
};

scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    cCnt = 0;
    for (i = 1; i <= sval.countrow; i++) {
        if (sval.NameValue(i, "CHK_FLAG") === "T") {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

scwin.etcCheck = function() {

    let ssval = comboFormGubun.ValueOfIndex("Column1", comboFormGubun.getSelectedIndex());
    if (etc_gubun.getValue() === '3') {
        if (confirm("대규모 법인여부를 선택하시겠습니까?")) {
            if (ssval !== "9") {
                if (txb_formXPath.value === "") {
                    alert("기본정보(테이블, 항목)와 서식(서식명, 항목)을 선택하십시오.");
                    etc_gubun.setValue("0");
                    return;
                }
            }
            scwin.mappingOne();
        } else {
            etc_gubun.setValue("0");
            scwin.mappingOne();
            return;
        }
    }
    if (etc_gubun.getValue() === '6') {
        if (confirm("대기업여부를 선택하시겠습니까?")) {
            scwin.mappingOne();
        }
    }
    if (etc_gubun.getValue() === '1') {
        if (confirm("지배회사의 연결자산 총액대비계산을 선택하시겠습니까?")) {
            if (ssval !== "9") {
                if (txb_formXPath.value === "") {
                    alert("기본정보(테이블, 항목)와 서식(서식명, 항목)을 선택하십시오.");
                    etc_gubun.setValue("0");
                    return;
                }
            }
            scwin.mappingOne();
        } else {
            etc_gubun.setValue("0");
            scwin.mappingOne();
            return;
        }
    } else {
        scwin.mappingOne();
    }
};

